#pragma once

#ifndef ADD_LAYER_NORM_KERNEL_H
#define ADD_LAYER_NORM_KERNEL_H

#include <algorithm>
#include <cmath>

#include "kernel_operator.h"
#include "kernel_common.h"
#include "add_layer_norm_tiling.h"

template <typename dataType>
class AddLayerNormKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR y, GM_ADDR gamma, GM_ADDR beta,
        GM_ADDR out, GM_ADDR mean, GM_ADDR invRms,
        GM_ADDR tilingGM, AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y), tiling_.M * tiling_.N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), tiling_.N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(beta), tiling_.N);
        outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(out), tiling_.M * tiling_.N);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(mean), tiling_.M);
        invRmsGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(invRms), tiling_.M);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();

            pipe_->InitBuffer(xInQueue_, 1, tiling_.N * sizeof(dataType));
            pipe_->InitBuffer(yInQueue_, 1, tiling_.N * sizeof(dataType));
            pipe_->InitBuffer(outOutQueue_, 1, tiling_.N * sizeof(dataType));
            pipe_->InitBuffer(gammaBuf_, tiling_.N * sizeof(dataType));
            pipe_->InitBuffer(betaBuf_, tiling_.N * sizeof(dataType));

            if constexpr (!std::is_same_v<dataType, float>) {
                pipe_->InitBuffer(xCastBuf_, tiling_.N * sizeof(float));
                pipe_->InitBuffer(yCastBuf_, tiling_.N * sizeof(float));
                pipe_->InitBuffer(gammaCastBuf_, tiling_.N * sizeof(float));
                pipe_->InitBuffer(betaCastBuf_, tiling_.N * sizeof(float));
            }
            pipe_->InitBuffer(computeBuf_, tiling_.N * sizeof(float));

            // Pre-load gamma/beta and pre-cast to fp32 (eliminates per-row Cast)
            AscendC::LocalTensor<dataType> gammaIn = gammaBuf_.Get<dataType>();
            AscendC::LocalTensor<dataType> betaIn = betaBuf_.Get<dataType>();
            AscendC::DataCopy(gammaIn, gammaGM_, static_cast<uint32_t>(tiling_.N));
            AscendC::DataCopy(betaIn, betaGM_, static_cast<uint32_t>(tiling_.N));
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            if constexpr (!std::is_same_v<dataType, float>) {
                gammaLocal_ = gammaCastBuf_.Get<float>();
                betaLocal_ = betaCastBuf_.Get<float>();
                AscendC::Cast(gammaLocal_, gammaIn, AscendC::RoundMode::CAST_NONE, tiling_.N);
                AscendC::Cast(betaLocal_, betaIn, AscendC::RoundMode::CAST_NONE, tiling_.N);
                AscendC::PipeBarrier<PIPE_V>();
            } else {
                gammaLocal_ = gammaBuf_.Get<float>();
                betaLocal_ = betaBuf_.Get<float>();
            }
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int subBlockIdx = AscendC::GetSubBlockIdx();

            for (int localIdx = 0; localIdx < tiling_.tasksPerCore; ++localIdx) {
                const int bx = coreIdx * tiling_.tasksPerCore + localIdx;
                if (bx >= BlockCount()) {
                    continue;
                }

                for (int row = 0; row < subBlockRows_; ++row) {
                    const int rowIdx = bx * tiling_.blockM + subBlockIdx * subBlockRows_ + row;
                    if (rowIdx < tiling_.M) {
                        ProcessRow(rowIdx);
                    }
                }
            }
        }
    }

private:
    __aicore__ inline int32_t BlockCount() const
    {
        return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM;
    }

    __aicore__ inline void CopyInXY(int32_t rowIdx)
    {
        xInQueue_.AllocTensor<dataType>(xInLocal_);
        AscendC::DataCopy(xInLocal_, xGM_[rowIdx * tiling_.N], static_cast<uint32_t>(tiling_.N));
        xInQueue_.EnQue(xInLocal_);

        yInQueue_.AllocTensor<dataType>(yInLocal_);
        AscendC::DataCopy(yInLocal_, yGM_[rowIdx * tiling_.N], static_cast<uint32_t>(tiling_.N));
        yInQueue_.EnQue(yInLocal_);
    }

    __aicore__ inline void CopyOutY(int32_t rowIdx)
    {
        outOutQueue_.DeQue<dataType>(outOutLocal_);
        AscendC::DataCopy(outGM_[rowIdx * tiling_.N], outOutLocal_, static_cast<uint32_t>(tiling_.N));
        outOutQueue_.FreeTensor(outOutLocal_);
    }

    __aicore__ inline void ComputeRow(int32_t rowIdx)
    {
        xInQueue_.DeQue<dataType>(xInLocal_);
        yInQueue_.DeQue<dataType>(yInLocal_);
        outOutQueue_.AllocTensor<dataType>(outOutLocal_);

        AscendC::LocalTensor<float> addFp32 = computeBuf_.Get<float>();

        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::LocalTensor<float> xFp32 = xInLocal_.template ReinterpretCast<float>();
            AscendC::LocalTensor<float> yFp32 = yInLocal_.template ReinterpretCast<float>();

            AscendC::Add(addFp32, xFp32, yFp32, tiling_.N);

            float sumVal = 0.0f, sumSqVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) {
                float val = addFp32(i);
                sumVal += val;
                sumSqVal += val * val;
            }

            float mean = sumVal * tiling_.invN;
            float meanSq = sumSqVal * tiling_.invN;
            meanGM_(rowIdx) = mean;
            float invRmsVal = 1.0f / sqrt(meanSq - mean * mean + tiling_.eps);
            invRmsGM_(rowIdx) = invRmsVal;

            AscendC::Adds(addFp32, addFp32, -mean, tiling_.N);
            AscendC::Muls(addFp32, addFp32, invRmsVal, tiling_.N);

            AscendC::LocalTensor<float> outFp32 = outOutLocal_.template ReinterpretCast<float>();
            AscendC::Mul(outFp32, addFp32, gammaLocal_, tiling_.N);
            AscendC::Add(outFp32, outFp32, betaLocal_, tiling_.N);
        } else {
            AscendC::LocalTensor<float> xFp32 = xCastBuf_.Get<float>();
            AscendC::LocalTensor<float> yFp32 = yCastBuf_.Get<float>();
            AscendC::Cast(xFp32, xInLocal_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::Cast(yFp32, yInLocal_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();

            AscendC::Add(addFp32, xFp32, yFp32, tiling_.N);

            float sumVal = 0.0f, sumSqVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) {
                float val = addFp32(i);
                sumVal += val;
                sumSqVal += val * val;
            }

            float mean = sumVal * tiling_.invN;
            float meanSq = sumSqVal * tiling_.invN;
            meanGM_(rowIdx) = mean;
            float invRmsVal = 1.0f / sqrt(meanSq - mean * mean + tiling_.eps);
            invRmsGM_(rowIdx) = invRmsVal;

            AscendC::Adds(addFp32, addFp32, -mean, tiling_.N);
            AscendC::Muls(addFp32, addFp32, invRmsVal, tiling_.N);

            // Use pre-casted gamma/beta from Init (eliminates per-row Cast overhead)
            AscendC::Mul(addFp32, addFp32, gammaLocal_, tiling_.N);
            AscendC::Add(addFp32, addFp32, betaLocal_, tiling_.N);

            AscendC::Cast(outOutLocal_, addFp32, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }

        outOutQueue_.EnQue(outOutLocal_);
        xInQueue_.FreeTensor(xInLocal_);
        yInQueue_.FreeTensor(yInLocal_);
    }

    __aicore__ inline void ProcessRow(int rowIdx)
    {
        CopyInXY(rowIdx);
        ComputeRow(rowIdx);
        CopyOutY(rowIdx);
    }

private:
    AddLayerNormTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int subBlockRows_{0};

    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> betaGM_;
    AscendC::GlobalTensor<dataType> outGM_;
    AscendC::GlobalTensor<float> meanGM_;
    AscendC::GlobalTensor<float> invRmsGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0> yInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gammaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> betaCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yInLocal_;
    AscendC::LocalTensor<dataType> outOutLocal_;
    AscendC::LocalTensor<float> gammaLocal_;
    AscendC::LocalTensor<float> betaLocal_;
};

#endif

pybind11.cpp.content:
#include <algorithm>

#include <pybind11/pybind11.h>
#include <torch/extension.h>

#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"

#include "add_layer_norm_tiling.h"

extern "C" void add_layer_norm_do_fp32(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling);
extern "C" void add_layer_norm_do_fp16(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling);
extern "C" void add_layer_norm_do_bf16(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y, uint8_t *gamma, uint8_t *beta,
    uint8_t *out, uint8_t *mean, uint8_t *invRms, uint8_t *tiling);

namespace add_layer_norm_ext {

using LaunchFn = void (*)(uint32_t, void *,
    uint8_t *, uint8_t *, uint8_t *, uint8_t *,
    uint8_t *, uint8_t *, uint8_t *, uint8_t *);

pybind11::tuple run_add_layer_norm(
    const at::Tensor &x, const at::Tensor &y,
    const at::Tensor &gamma, const at::Tensor &beta,
    double eps = 1e-5)
{
    TORCH_CHECK(x.dim() == 2, "x must be [M, N]");
    TORCH_CHECK(y.dim() == 2, "y must be [M, N]");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be [N]");
    TORCH_CHECK(beta.dim() == 1, "beta must be [N]");
    TORCH_CHECK(x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kHalf ||
                x.scalar_type() == at::kBFloat16, "x must be float32/float16/bfloat16");
    TORCH_CHECK(y.scalar_type() == x.scalar_type(), "dtype mismatch");
    TORCH_CHECK(gamma.scalar_type() == x.scalar_type(), "dtype mismatch");
    TORCH_CHECK(beta.scalar_type() == x.scalar_type(), "dtype mismatch");
    TORCH_CHECK(x.is_contiguous() && y.is_contiguous(), "must be contiguous");
    TORCH_CHECK(x.sizes() == y.sizes(), "x,y shape mismatch");
    TORCH_CHECK(x.sizes()[1] == gamma.sizes()[0], "gamma shape mismatch");
    TORCH_CHECK(x.sizes()[1] == beta.sizes()[0], "beta shape mismatch");

    const auto m = static_cast<int32_t>(x.sizes()[0]);
    const auto n = static_cast<int32_t>(x.sizes()[1]);

    const int32_t mNum = (m + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    const int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES, mNum);
    const int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    at::Tensor out = at::empty_like(x);
    at::Tensor mean = at::empty({m}, x.options().dtype(at::kFloat));
    at::Tensor invRms = at::empty({m}, x.options().dtype(at::kFloat));

    at::Tensor tilingCpu = at::empty(
        {static_cast<long>(sizeof(AddLayerNormTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *t = reinterpret_cast<AddLayerNormTiling *>(tilingCpu.data_ptr());
    t->M = m; t->N = n;
    t->blockM = DEFAULT_BLOCK_M;
    t->usedCoreNum = usedCoreNum;
    t->tasksPerCore = tasksPerCore;
    t->eps = static_cast<float>(eps);
    t->invN = 1.0f / static_cast<float>(n);
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
    LaunchFn launch = nullptr;
    if (x.scalar_type() == at::kFloat) launch = add_layer_norm_do_fp32;
    else if (x.scalar_type() == at::kHalf) launch = add_layer_norm_do_fp16;
    else if (x.scalar_type() == at::kBFloat16) launch = add_layer_norm_do_bf16;
    else TORCH_CHECK(false, "unsupported dtype");

    launch(usedCoreNum, aclStream,
        static_cast<uint8_t *>(const_cast<void *>(x.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(y.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(gamma.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(beta.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(out.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(mean.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(invRms.storage().data())),
        static_cast<uint8_t *>(const_cast<void *>(tilingNpu.storage().data())));
    return pybind11::make_tuple(out, mean, invRms);
}

}  // namespace add_layer_norm_ext

PYBIND11_MODULE(_add_layer_norm_ext, m)
{
    m.doc() = "add_layer_norm extension";
    m.def("run_add_layer_norm", &add_layer_norm_ext::run_add_layer_norm, "");
}

