#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "add_rms_norm_tiling.h"
extern "C" void arn_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace arn_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_add_rms_norm(const at::Tensor &x, const at::Tensor &residual, double eps=1e-6) {
    TORCH_CHECK(x.dim()==2&&residual.dim()==2,"must be [M,N]");
    TORCH_CHECK(x.scalar_type()==at::kHalf,"fp16 only");
    TORCH_CHECK(x.sizes()==residual.sizes(),"shape mismatch");
    TORCH_CHECK(x.is_contiguous(),"contiguous");
    const auto m=static_cast<int32_t>(x.sizes()[0]), n=static_cast<int32_t>(x.sizes()[1]);
    const int32_t mNum=(m+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty_like(x);
    at::Tensor tc=at::empty({sizeof(ArnKernelTiling)},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<ArnKernelTiling*>(tc.data_ptr());
    t->M=m; t->N=n; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    t->eps=static_cast<float>(eps); t->invN=1.0f/static_cast<float>(n);
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    arn_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(residual.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_add_rms_norm_ext, m) { m.def("run_add_rms_norm",&arn_ext::run_add_rms_norm,""); }

