add_rms_norm_kernel.h.content:
#pragma once
#ifndef ARN_KERNEL_H
#define ARN_KERNEL_H
#include <cmath>
#include "kernel_operator.h"
#include "kernel_common.h"
#include "add_rms_norm_tiling.h"

template <typename T>
class ArnKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR r, GM_ADDR y, GM_ADDR tm, AscendC::TPipe *p) {
        CopyTiling(&t_, tm);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), t_.M * t_.N);
        rGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(r), t_.M * t_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), t_.M * t_.N);
        if ASCEND_IS_AIV {
            pipe_ = p; sr_ = t_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQ_, 1, t_.N * sizeof(T));
            pipe_->InitBuffer(rInQ_, 1, t_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, t_.N * sizeof(T));
