pybind11::tuple run_add_rms_norm_dynamic_quant(const at::Tensor &x, const at::Tensor &residual, double eps=1e-6) {
    TORCH_CHECK(x.dim()==2&&residual.dim()==2,"[M,N]"); TORCH_CHECK(x.scalar_type()==at::kHalf,"fp16 only");
