    at::Tensor yq=at::empty({m,n}, x.options().dtype(at::kByte));
    at::Tensor rowMax=at::empty({m}, x.options().dtype(at::kFloat));
    at::Tensor tc=at::empty({static_cast<long>(sizeof(ArndqKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<ArndqKernelTiling*>(tc.data_ptr());
    t->M=m; t->N=n; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    t->eps=static_cast<float>(eps); t->invN=1.0f/static_cast<float>(n);
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    arndq_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(residual.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(yq.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(rowMax.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
