#pragma once
#ifndef ARNDQ_KERNEL_H
#define ARNDQ_KERNEL_H
#include <cmath>
#include "kernel_operator.h"
#include "kernel_common.h"
#include "arndq_tiling.h"

template <typename T>
class ArndqKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR r, GM_ADDR y, GM_ADDR yq, GM_ADDR maxA, GM_ADDR tm, AscendC::TPipe *p) {
        CopyTiling(&t_, tm);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), t_.M * t_.N);
        rGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(r), t_.M * t_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), t_.M * t_.N);
        yqGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int8_t *>(yq), t_.M * t_.N);
        maxGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(maxA), t_.M);
        if ASCEND_IS_AIV {
            pipe_ = p; sr_ = t_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQ_, 1, t_.N * sizeof(T));
            pipe_->InitBuffer(rInQ_, 1, t_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, t_.N * sizeof(T));
            if constexpr (!std::is_same_v<T, float>) {
                pipe_->InitBuffer(castX_, t_.N * sizeof(float));
                pipe_->InitBuffer(castR_, t_.N * sizeof(float));
            }
            pipe_->InitBuffer(comp_, t_.N * sizeof(float));
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < t_.tasksPerCore; ++li) {
                const int bx = ci * t_.tasksPerCore + li; if (bx >= BlockCount()) continue;
                for (int r = 0; r < sr_; ++r) {
                    const int ri = bx * t_.blockM + si * sr_ + r; if (ri < t_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (t_.M + t_.blockM - 1) / t_.blockM; }
    __aicore__ inline void ProcessRow(int32_t ri) {
        xInQ_.AllocTensor<T>(xL_); rInQ_.AllocTensor<T>(rL_);
        AscendC::DataCopy(xL_, xGM_[ri * t_.N], t_.N); xInQ_.EnQue(xL_);
        AscendC::DataCopy(rL_, rGM_[ri * t_.N], t_.N); rInQ_.EnQue(rL_);
        xInQ_.DeQue<T>(xL_); rInQ_.DeQue<T>(rL_);
        yOutQ_.AllocTensor<T>(yL_);
        auto addFp32 = comp_.Get<float>();

        if constexpr (std::is_same_v<T, float>) {
            auto xFp32 = xL_.template ReinterpretCast<float>();
            auto rFp32 = rL_.template ReinterpretCast<float>();
            AscendC::Add(addFp32, xFp32, rFp32, t_.N);
            float sumSq = 0.0f;
            for (int32_t i = 0; i < t_.N; ++i) { float v = addFp32(i); sumSq += v * v; }
            float invRms = 1.0f / sqrt(sumSq * t_.invN + t_.eps);
            AscendC::Muls(addFp32, addFp32, invRms, t_.N);
            // Find per-row max abs
            float rowMax = 0.0f;
            for (int32_t i = 0; i < t_.N; ++i) { float v = addFp32(i); if (v < 0) v = -v; if (v > rowMax) rowMax = v; }
            maxGM_.SetValue(ri, rowMax);
            auto yFp32 = yL_.template ReinterpretCast<float>();
            for (int32_t i = 0; i < t_.N; ++i) yFp32(i) = addFp32(i);
        } else {
            auto xFp32 = castX_.Get<float>(); auto rFp32 = castR_.Get<float>();
            AscendC::Cast(xFp32, xL_, AscendC::RoundMode::CAST_NONE, t_.N);
            AscendC::Cast(rFp32, rL_, AscendC::RoundMode::CAST_NONE, t_.N);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(addFp32, xFp32, rFp32, t_.N);
            float sumSq = 0.0f;
            for (int32_t i = 0; i < t_.N; ++i) { float v = addFp32(i); sumSq += v * v; }
            float invRms = 1.0f / sqrt(sumSq * t_.invN + t_.eps);
            AscendC::Muls(addFp32, addFp32, invRms, t_.N);
            float rowMax = 0.0f;
            for (int32_t i = 0; i < t_.N; ++i) { float v = addFp32(i); if (v < 0) v = -v; if (v > rowMax) rowMax = v; }
            maxGM_.SetValue(ri, rowMax);
            AscendC::Cast(yL_, addFp32, AscendC::RoundMode::CAST_NONE, t_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQ_.EnQue(yL_); yOutQ_.DeQue<T>(yL_);
        AscendC::DataCopy(yGM_[ri * t_.N], yL_, t_.N);
        yOutQ_.FreeTensor(yL_); xInQ_.FreeTensor(xL_); rInQ_.FreeTensor(rL_);
    }
private:
    ArndqKernelTiling t_{}; AscendC::TPipe *pipe_{}; int sr_{};
    AscendC::GlobalTensor<T> xGM_, rGM_, yGM_;
    AscendC::GlobalTensor<int8_t> yqGM_;
    AscendC::GlobalTensor<float> maxGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> xInQ_, rInQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT,0> yOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> castX_, castR_, comp_;
    AscendC::LocalTensor<T> xL_, rL_, yL_;
};
