#pragma once
#ifndef AP_KERNEL_H
#define AP_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "ap_tiling.h"

template <typename T>
class APKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.inTotal);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.M * tiling_.N);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            // No queues needed — use scalar GetValue/SetValue
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + si * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }
    __aicore__ inline void ProcessRow(int32_t ri) {
        int32_t c = ri / tiling_.Ho, h = ri % tiling_.Ho;
        int32_t inChBase = c * tiling_.inChStride;
        int32_t outBase = (c * tiling_.Ho + h) * tiling_.N;
        for (int32_t w = 0; w < tiling_.N; ++w) {
            float sum = xGM_.GetValue(inChBase + (h*2)*tiling_.W + w*2)
                      + xGM_.GetValue(inChBase + (h*2)*tiling_.W + w*2 + 1)
                      + xGM_.GetValue(inChBase + (h*2+1)*tiling_.W + w*2)
                      + xGM_.GetValue(inChBase + (h*2+1)*tiling_.W + w*2 + 1);
            yGM_.SetValue(outBase + w, static_cast<T>(sum * 0.25f));
        }
    }
private:
    APKernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> xGM_, yGM_;
};
#endif

