#pragma once
#ifndef BMM_KERNEL_H
#define BMM_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "bmm_tiling.h"

template <typename T>
class BmmKernel {
public:
    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR tm, AscendC::TPipe *p) {
        CopyTiling(&t_, tm);
        aGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(a), t_.M_total * t_.K);
        bGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(b), t_.M_total / t_.M * t_.K * t_.N);
        cGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(c), t_.M_total * t_.N);
        if ASCEND_IS_AIV { pipe_ = p; sr_ = t_.blockM / AscendC::GetSubBlockNum(); }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < t_.tasksPerCore; ++li) {
                const int bx = ci * t_.tasksPerCore + li; if (bx >= BlockCount()) continue;
                for (int r = 0; r < sr_; ++r) {
                    const int ri = bx * t_.blockM + si * sr_ + r; if (ri < t_.M_total) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (t_.M_total + t_.blockM - 1) / t_.blockM; }
    __aicore__ inline void ProcessRow(int32_t ri) {
        int32_t b = ri / t_.M;  // batch index
        int32_t row = ri % t_.M; // row within batch
        int32_t aBase = b * t_.M * t_.K + row * t_.K;
        int32_t bBase = b * t_.K * t_.N;
        int32_t cBase = b * t_.M * t_.N + row * t_.N;
        for (int32_t col = 0; col < t_.N; ++col) {
            float sum = 0.0f;
            for (int32_t k = 0; k < t_.K; ++k)
                sum += static_cast<float>(aGM_.GetValue(aBase + k)) *
                       static_cast<float>(bGM_.GetValue(bBase + k * t_.N + col));
            cGM_.SetValue(cBase + col, static_cast<T>(sum));
        }
    }
private:
    BmmKernelTiling t_{}; AscendC::TPipe *pipe_{}; int sr_{};
    AscendC::GlobalTensor<T> aGM_, bGM_, cGM_;
};
#endif

