        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < t_.tasksPerCore; ++li) {
                const int bx = ci * t_.tasksPerCore + li; if (bx >= BlockCount()) continue;
                for (int r = 0; r < sr_; ++r) {
                    const int ri = bx * t_.blockM + si * sr_ + r; if (ri < t_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (t_.M + t_.blockM - 1) / t_.blockM; }
    __aicore__ inline void ProcessRow(int32_t ri) {
        int32_t h = ri / t_.S, i = ri % t_.S;
        int32_t kh = h * t_.Hk / t_.Hq;
        int32_t qBase = h * t_.S * t_.N + i * t_.N;
        int32_t kvBase = kh * t_.Skv * t_.N;
        int32_t yBase = h * t_.S * t_.N + i * t_.N;

        auto scores = scoreBuf_.Get<float>();

        // Compute all dot products
        for (int32_t j = 0; j < t_.Skv; ++j) {
            float dot = 0.0f;
            for (int32_t d = 0; d < t_.N; ++d)
                dot += static_cast<float>(qGM_.GetValue(qBase + d)) *
                       static_cast<float>(kGM_.GetValue(kvBase + j * t_.N + d));
            scores(j) = dot * t_.invSqrtD;
        }

        // Find max
        float maxVal = scores(0);
        for (int32_t j = 1; j < t_.Skv; ++j) { float v = scores(j); if (v > maxVal) maxVal = v; }

        // Subtract max
        for (int32_t j = 0; j < t_.Skv; ++j) scores(j) -= maxVal;
        // Vector exp
        AscendC::Exp(scores, scores, t_.Skv);
        // Sum
        float sumExp = 0.0f;
        for (int32_t j = 0; j < t_.Skv; ++j) sumExp += scores(j);
        // Normalize
        float invSum = 1.0f / sumExp;
        for (int32_t j = 0; j < t_.Skv; ++j) scores(j) *= invSum;

        // Weighted V sum
        for (int32_t d = 0; d < t_.N; ++d) {
            float val = 0.0f;
            for (int32_t j = 0; j < t_.Skv; ++j)
                val += scores(j) * static_cast<float>(vGM_.GetValue(kvBase + j * t_.N + d));
            yGM_.SetValue(yBase + d, static_cast<T>(val));
        }
    }
private:
    FAKernelTiling t_{}; AscendC::TPipe *pipe_{}; int sr_{};
    AscendC::GlobalTensor<T> qGM_, kGM_, vGM_, yGM_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scoreBuf_;
};
#endif

