#ifndef GELU_MUL_KERNEL_H
#define GELU_MUL_KERNEL_H

#pragma once

#include "kernel_operator.h"
#include "gelu_mul_tiling.h"

__aicore__ inline void CopyTiling(GeluMulTiling *tiling, GM_ADDR tilingGM)
{
    int32_t *dst = reinterpret_cast<int32_t *>(tiling);
    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    for (size_t i = 0; i < sizeof(GeluMulTiling) / sizeof(int32_t); ++i) {
        dst[i] = src[i];
    }
}

template<typename T>
class GeluMulKernel {
public:
    __aicore__ inline void Init(GM_ADDR xGM, GM_ADDR yGM, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(xGM), tiling_.twoInter * tiling_.B_S);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(yGM), tiling_.totalElements);

        pipe_ = pipe;

        uint32_t bufSize = tiling_.blockSize * sizeof(T);
        pipe_->InitBuffer(x0Queue_, 1, bufSize);
        pipe_->InitBuffer(x1Queue_, 1, bufSize);
        pipe_->InitBuffer(yQueue_, 1, bufSize);
        uint32_t fp32BufSize = tiling_.blockSize * sizeof(float);
        pipe_->InitBuffer(tmp1Buf_, fp32BufSize);
        pipe_->InitBuffer(tmp2Buf_, fp32BufSize);
        pipe_->InitBuffer(tmp3Buf_, fp32BufSize);
        pipe_->InitBuffer(tmp4Buf_, fp32BufSize);
        pipe_->InitBuffer(tmp5Buf_, fp32BufSize);
    }

    __aicore__ inline void Process() {
        uint32_t blockIdx = AscendC::GetBlockIdx();
        if (blockIdx >= tiling_.blockCount) {
            return;
        }

        uint32_t offset = blockIdx * tiling_.blockSize;
        uint32_t count = (tiling_.tailSize > 0 && blockIdx == tiling_.blockCount - 1)
                         ? tiling_.tailSize : tiling_.blockSize;

        CopyIn(offset, count);
        Compute(count);
        CopyOut(offset, count);
    }

private:
    __aicore__ inline void CopyIn(uint32_t offset, uint32_t count) {
        uint32_t row = offset / tiling_.half;
        uint32_t col = offset % tiling_.half;

        uint32_t remaining = count;
        uint32_t currentRow = row;
        uint32_t currentCol = col;

        while (remaining > 0) {
            uint32_t colRemaining = tiling_.half - currentCol;
            uint32_t chunkSize = (remaining <= colRemaining) ? remaining : colRemaining;

            x0Queue_.AllocTensor<T>(x0Local_);
            x1Queue_.AllocTensor<T>(x1Local_);

            AscendC::DataCopyExtParams params;
            params.blockCount = 1;
            params.blockLen = chunkSize * sizeof(T);
            params.srcStride = (tiling_.half - chunkSize) * sizeof(T);
            params.dstStride = 0;
            params.rsv = 0;

            AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};

            uint32_t x0Offset = currentRow * tiling_.twoInter + currentCol;
            AscendC::DataCopyPad(x0Local_, xGM_[x0Offset], params, padParams);

            uint32_t x1Offset = currentRow * tiling_.twoInter + tiling_.half + currentCol;
            AscendC::DataCopyPad(x1Local_, xGM_[x1Offset], params, padParams);

            x0Queue_.EnQue(x0Local_);
            x1Queue_.EnQue(x1Local_);

            remaining -= chunkSize;
            currentRow++;
            currentCol = 0;
        }
    }

    __aicore__ inline void Compute(uint32_t count) {
        x0Queue_.DeQue<T>(x0Local_);
        x1Queue_.DeQue<T>(x1Local_);
        yQueue_.AllocTensor<T>(yLocal_);

        // Cast to fp32
        AscendC::LocalTensor<float> x0Fp32 = tmp1Buf_.Get<float>();
        AscendC::LocalTensor<float> x1Fp32 = tmp2Buf_.Get<float>();
        AscendC::LocalTensor<float> geluFp32 = tmp3Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp1 = tmp4Buf_.Get<float>();
        AscendC::LocalTensor<float> tmp2 = tmp5Buf_.Get<float>();

        AscendC::Cast(x0Fp32, x0Local_, AscendC::RoundMode::CAST_ROUND, count);
        AscendC::Cast(x1Fp32, x1Local_, AscendC::RoundMode::CAST_ROUND, count);

        // GELU(x) = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
        // tmp1 = x^2
        AscendC::Mul(tmp1, x0Fp32, x0Fp32, count);
        // tmp2 = x^3
        AscendC::Mul(tmp2, x0Fp32, tmp1, count);
        // geluFp32 = 0.044715 * x^3
        AscendC::Muls(geluFp32, tmp2, 0.044715f, count);
        // geluFp32 = x + 0.044715 * x^3
        AscendC::Add(geluFp32, x0Fp32, geluFp32, count);
        // geluFp32 = sqrt(2/pi) * (x + 0.044715 * x^3)
        AscendC::Muls(geluFp32, geluFp32, 0.79788456f, count);
        // geluFp32 = tanh(...)
        AscendC::Tanh(geluFp32, geluFp32, count);
        // geluFp32 = 1 + tanh(...)
        AscendC::Adds(geluFp32, geluFp32, 1.0f, count);
        // geluFp32 = x * (1 + tanh(...))
        AscendC::Mul(geluFp32, x0Fp32, geluFp32, count);
        // geluFp32 = 0.5 * x * (1 + tanh(...)) = gelu(x)
        AscendC::Muls(geluFp32, geluFp32, 0.5f, count);
        // geluFp32 = gelu(x) * x1
        AscendC::Mul(geluFp32, geluFp32, x1Fp32, count);

        AscendC::Cast(yLocal_, geluFp32, AscendC::RoundMode::CAST_ROUND, count);

        x0Queue_.FreeTensor(x0Local_);
        x1Queue_.FreeTensor(x1Local_);
        yQueue_.EnQue<T>(yLocal_);
    }

    __aicore__ inline void CopyOut(uint32_t offset, uint32_t count) {
        yQueue_.DeQue<T>(yLocal_);

        AscendC::DataCopyExtParams params;
        params.blockCount = 1;
        params.blockLen = count * sizeof(T);
        params.srcStride = 0;
        params.dstStride = 0;
        params.rsv = 0;

        AscendC::DataCopyPad(yGM_[offset], yLocal_, params);

        yQueue_.FreeTensor(yLocal_);
    }

private:
    GeluMulTiling tiling_;
    AscendC::GlobalTensor<T> xGM_;
    AscendC::GlobalTensor<T> yGM_;
    AscendC::TPipe *pipe_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> x0Queue_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0> x1Queue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> yQueue_;

    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp1Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp2Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp3Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp4Buf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp5Buf_;

    AscendC::LocalTensor<T> x0Local_;
    AscendC::LocalTensor<T> x1Local_;
    AscendC::LocalTensor<T> yLocal_;
};

#endif  // GELU_MUL_KERNEL_H

