#ifndef GELU_MUL_TILING_H
#define GELU_MUL_TILING_H

#include <cstdint>

struct GeluMulTiling {
    uint32_t totalElements;   // B_S * half
    uint32_t blockCount;     // number of blocks
    uint32_t blockSize;      // elements per block (aligned to 128)
    uint32_t tailSize;       // remaining elements in last block
    uint32_t B_S;           // batch * seq
    uint32_t half;           // intermediate size (half of 2*intermediate)
    uint32_t twoInter;       // total width = 2 * half
};

