#include <pybind11/pybind11.h>
#include <torch/extension.h>
#include "acl/acl.h"
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "layer_norm_v3_tiling.h"
extern "C" void layer_norm_v3_do_fp32(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
extern "C" void layer_norm_v3_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
namespace layer_norm_v3_ext {
using LF = void (*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_layer_norm_v3(const at::Tensor &x, const at::Tensor &gamma, const at::Tensor &beta, double eps=1e-5) {
    TORCH_CHECK(x.dim()==2&&gamma.dim()==1&&beta.dim()==1,"shape error");
    TORCH_CHECK(x.scalar_type()==at::kFloat||x.scalar_type()==at::kHalf,"unsupported dtype");
    TORCH_CHECK(x.is_contiguous()&&gamma.is_contiguous()&&beta.is_contiguous(),"must be contiguous");
    const auto m=static_cast<int32_t>(x.sizes()[0]), n=static_cast<int32_t>(x.sizes()[1]);
    const int32_t mNum=(m+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    auto y=at::empty_like(x); auto mean=at::empty({m},x.options().dtype(at::kFloat)); auto istd=at::empty({m},x.options().dtype(at::kFloat));
    auto tc=at::empty({static_cast<long>(sizeof(LayerNormV3KernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<LayerNormV3KernelTiling*>(tc.data_ptr());
    t->M=m; t->N=n; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc; t->eps=static_cast<float>(eps); t->invN=1.0f/static_cast<float>(n);
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    LF l=nullptr;
    if(x.scalar_type()==at::kFloat) l=layer_norm_v3_do_fp32;
    else if(x.scalar_type()==at::kHalf) l=layer_norm_v3_do_fp16;
    else TORCH_CHECK(false,"unsupported dtype");
    l(uc,stm,
      static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),
      static_cast<uint8_t*>(const_cast<void*>(gamma.storage().data())),
      static_cast<uint8_t*>(const_cast<void*>(beta.storage().data())),
      static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
      static_cast<uint8_t*>(const_cast<void*>(mean.storage().data())),
      static_cast<uint8_t*>(const_cast<void*>(istd.storage().data())),
      static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y,mean,istd);
}}
PYBIND11_MODULE(_layer_norm_v3_ext, m) { m.def("run_layer_norm_v3",&layer_norm_v3_ext::run_layer_norm_v3,""); }

