layer_norm_v3_kernel.h.content:
#pragma once
#ifndef LAYER_NORM_V3_KERNEL_H
#define LAYER_NORM_V3_KERNEL_H
#include <cmath>
#include "kernel_operator.h"
#include "kernel_common.h"
#include "layer_norm_v3_tiling.h"

template <typename T>
class LayerNormV3Kernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
                                GM_ADDR mean, GM_ADDR invStd, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.M * tiling_.N);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(gamma), tiling_.N);
        betaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(beta), tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.M * tiling_.N);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(mean), tiling_.M);
        invStdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(invStd), tiling_.M);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(gBuf_, tiling_.N * sizeof(T));
            pipe_->InitBuffer(bBuf_, tiling_.N * sizeof(T));
            if constexpr (!std::is_same_v<T, float>) {
                pipe_->InitBuffer(xCast_, tiling_.N * sizeof(float));
            }
            pipe_->InitBuffer(cBuf_, tiling_.N * sizeof(float));
            // Pre-load gamma/beta
            auto gIn = gBuf_.Get<T>(); auto bIn = bBuf_.Get<T>();
            AscendC::DataCopy(gIn, gammaGM_, static_cast<uint32_t>(tiling_.N));
            AscendC::DataCopy(bIn, betaGM_, static_cast<uint32_t>(tiling_.N));
            AscendC::PipeBarrier<PIPE_MTE2>(); AscendC::PipeBarrier<PIPE_ALL>();
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + si * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }
    __aicore__ inline void CopyIn(int32_t ri) {
        xInQ_.AllocTensor<T>(xInL_);
        AscendC::DataCopy(xInL_, xGM_[ri * tiling_.N], static_cast<uint32_t>(tiling_.N));
        xInQ_.EnQue(xInL_);
    }
    __aicore__ inline void CopyOut(int32_t ri) {
        yOutQ_.DeQue<T>(yOutL_);
        AscendC::DataCopy(yGM_[ri * tiling_.N], yOutL_, static_cast<uint32_t>(tiling_.N));
        yOutQ_.FreeTensor(yOutL_);
    }
    __aicore__ inline void ComputeRow(int32_t ri) {
        xInQ_.DeQue<T>(xInL_); yOutQ_.AllocTensor<T>(yOutL_);
        auto addFp32 = cBuf_.Get<float>();
        if constexpr (std::is_same_v<T, float>) {
            auto xFp32 = xInL_.template ReinterpretCast<float>();
            float s=0, sq=0;
            for (int32_t i=0; i<tiling_.N; ++i) { float v=xFp32(i); s+=v; sq+=v*v; }
            float mean=s*tiling_.invN, invStd=1.0f/sqrt(sq*tiling_.invN-mean*mean+tiling_.eps);
            meanGM_(ri)=mean; invStdGM_(ri)=invStd;
            AscendC::Adds(addFp32,xFp32,-mean,tiling_.N);
            AscendC::Muls(addFp32,addFp32,invStd,tiling_.N);
            auto gFp32=gBuf_.Get<float>(); auto bFp32=bBuf_.Get<float>();
            auto yFp32=yOutL_.template ReinterpretCast<float>();
            AscendC::Mul(yFp32,addFp32,gFp32,tiling_.N);
            AscendC::Add(yFp32,yFp32,bFp32,tiling_.N);
        } else {
            auto xFp32=xCast_.Get<float>();
            AscendC::Cast(xFp32,xInL_,AscendC::RoundMode::CAST_NONE,tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
            float s=0, sq=0;
            for (int32_t i=0; i<tiling_.N; ++i) { float v=xFp32(i); s+=v; sq+=v*v; }
            float mean=s*tiling_.invN, invStd=1.0f/sqrt(sq*tiling_.invN-mean*mean+tiling_.eps);
            meanGM_(ri)=mean; invStdGM_(ri)=invStd;
            AscendC::Adds(addFp32,xFp32,-mean,tiling_.N);
            AscendC::Muls(addFp32,addFp32,invStd,tiling_.N);
            // Cast gamma/beta to fp32 using xCast_ (reuse)
            auto gFp32=xCast_.Get<float>(); auto gIn=gBuf_.Get<T>();
            AscendC::Cast(gFp32,gIn,AscendC::RoundMode::CAST_NONE,tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Mul(addFp32,addFp32,gFp32,tiling_.N);
            auto bFp32=xCast_.Get<float>(); auto bIn=bBuf_.Get<T>();
            AscendC::Cast(bFp32,bIn,AscendC::RoundMode::CAST_NONE,tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::Add(addFp32,addFp32,bFp32,tiling_.N);
            AscendC::Cast(yOutL_,addFp32,AscendC::RoundMode::CAST_NONE,tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQ_.EnQue(yOutL_); xInQ_.FreeTensor(xInL_);
    }
    __aicore__ inline void ProcessRow(int ri) { CopyIn(ri); ComputeRow(ri); CopyOut(ri); }
private:
    LayerNormV3KernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> xGM_, gammaGM_, betaGM_, yGM_;
    AscendC::GlobalTensor<float> meanGM_, invStdGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> xInQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT,0> yOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> gBuf_, bBuf_, xCast_, cBuf_;
    AscendC::LocalTensor<T> xInL_, yOutL_;
};
#endif

