namespace msrpb_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_masked_softmax_with_rel_pos_bias(const at::Tensor &qk, const at::Tensor &mask, const at::Tensor &bias) {
    TORCH_CHECK(qk.dim()==5,"qk must be [B,W,N,S1,S2]"); TORCH_CHECK(qk.scalar_type()==at::kHalf,"fp16 only");
    TORCH_CHECK(qk.is_contiguous(),"must be contiguous");
    const auto M=static_cast<int32_t>(qk.numel()/qk.sizes()[4]), N=static_cast<int32_t>(qk.sizes()[4]);
    auto mask_bc=mask.expand_as(qk).contiguous();
    auto bias_bc=bias.expand_as(qk).contiguous();
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty_like(qk);
    at::Tensor tc=at::empty({static_cast<long>(sizeof(MSRPBKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<MSRPBKernelTiling*>(tc.data_ptr());
    t->M=M; t->N=N; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    msrpb_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(qk.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(mask_bc.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(bias_bc.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_msrpb_ext, m) { m.def("run_masked_softmax_with_rel_pos_bias",&msrpb_ext::run_masked_softmax_with_rel_pos_bias,""); }

