pybind11::tuple run_mat_mul_v3(const at::Tensor &a, const at::Tensor &b) {
    TORCH_CHECK(a.dim()==2&&b.dim()==2,"must be [M,K] and [K,N]");
    TORCH_CHECK(a.scalar_type()==at::kHalf,"fp16 only"); TORCH_CHECK(a.sizes()[1]==b.sizes()[0],"K mismatch");
    TORCH_CHECK(a.is_contiguous()&&b.is_contiguous(),"must be contiguous");
    const auto M=static_cast<int32_t>(a.sizes()[0]), K=static_cast<int32_t>(a.sizes()[1]), N=static_cast<int32_t>(b.sizes()[1]);
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor c=at::empty({M,N},a.options());
    at::Tensor tc=at::empty({static_cast<long>(sizeof(MMKernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<MMKernelTiling*>(tc.data_ptr());
    t->M=M; t->K=K; t->N=N; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1); auto stm=c10_npu::getCurrentNPUStream().stream(false);
    mm_do_fp16(uc,stm,
        static_cast<uint8_t*>(const_cast<void*>(a.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(b.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(c.storage().data())),
        static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(c);
}}
