extern "C" void softmax_v2_do_fp16(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
namespace softmax_v2_ext {
using LF=void(*)(uint32_t,void*,uint8_t*,uint8_t*,uint8_t*);
pybind11::tuple run_softmax_v2(const at::Tensor &x) {
    TORCH_CHECK(x.dim()==4,"x must be [B,H,S,S]");
    TORCH_CHECK(x.scalar_type()==at::kFloat||x.scalar_type()==at::kHalf,"unsupported");
    TORCH_CHECK(x.is_contiguous(),"must be contiguous");
    const auto B=static_cast<int32_t>(x.sizes()[0]), H=static_cast<int32_t>(x.sizes()[1]);
    const auto S=static_cast<int32_t>(x.sizes()[2]);
    const auto M=B*H*S, N=S;
    const int32_t mNum=(M+DEFAULT_BLOCK_M-1)/DEFAULT_BLOCK_M;
    const int32_t uc=std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,mNum);
    const int32_t tpc=(mNum+uc-1)/uc;
    at::Tensor y=at::empty_like(x);
    at::Tensor tc=at::empty({static_cast<long>(sizeof(SoftmaxV2KernelTiling))},at::device(at::kCPU).dtype(at::kByte));
    auto *t=reinterpret_cast<SoftmaxV2KernelTiling*>(tc.data_ptr());
    t->M=M; t->N=N; t->blockM=DEFAULT_BLOCK_M; t->usedCoreNum=uc; t->tasksPerCore=tpc;
    auto tn=tc.to(at::kPrivateUse1);
    auto stm=c10_npu::getCurrentNPUStream().stream(false);
    LF l=nullptr;
    if(x.scalar_type()==at::kFloat) l=softmax_v2_do_fp32;
    else if(x.scalar_type()==at::kHalf) l=softmax_v2_do_fp16;
    else TORCH_CHECK(false,"unsupported");
    l(uc,stm,static_cast<uint8_t*>(const_cast<void*>(x.storage().data())),static_cast<uint8_t*>(const_cast<void*>(y.storage().data())),static_cast<uint8_t*>(const_cast<void*>(tn.storage().data())));
    return pybind11::make_tuple(y);
}}
PYBIND11_MODULE(_softmax_v2_ext, m) { m.def("run_softmax_v2",&softmax_v2_ext::run_softmax_v2,""); }

