softmax_v2_kernel.h.content:
#pragma once
#ifndef SOFTMAX_V2_KERNEL_H
#define SOFTMAX_V2_KERNEL_H
#include <cmath>
#include "kernel_operator.h"
#include "kernel_common.h"
#include "softmax_v2_tiling.h"

template <typename T>
class SoftmaxV2Kernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.M * tiling_.N);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, tiling_.N * sizeof(T));
            if constexpr (!std::is_same_v<T, float>) {
                pipe_->InitBuffer(workBuf_, tiling_.N * sizeof(float));
            }
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + si * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }
    __aicore__ inline void CopyIn(int32_t ri) {
        xInQ_.AllocTensor<T>(xInL_); AscendC::DataCopy(xInL_, xGM_[ri * tiling_.N], tiling_.N); xInQ_.EnQue(xInL_);
    }
    __aicore__ inline void CopyOut(int32_t ri) {
        yOutQ_.DeQue<T>(yOutL_); AscendC::DataCopy(yGM_[ri * tiling_.N], yOutL_, tiling_.N); yOutQ_.FreeTensor(yOutL_);
    }
    __aicore__ inline void ComputeRow(int32_t ri) {
        xInQ_.DeQue<T>(xInL_); yOutQ_.AllocTensor<T>(yOutL_);

        if constexpr (std::is_same_v<T, float>) {
            auto data = xInL_.template ReinterpretCast<float>();
            auto out  = yOutL_.template ReinterpretCast<float>();
            // Find max
            float maxVal = data(0);
            for (int32_t i = 1; i < tiling_.N; ++i) { float v = data(i); if (v > maxVal) maxVal = v; }
            // Copy data to out, subtract max
            for (int32_t i = 0; i < tiling_.N; ++i) out(i) = data(i) - maxVal;
            // Vector exp
            AscendC::Exp(out, out, tiling_.N);
            // Scalar sum
            float sumVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) sumVal += out(i);
            // Vector divide by sum
            float invSum = 1.0f / sumVal;
            AscendC::Muls(out, out, invSum, tiling_.N);
        } else {
            auto data = workBuf_.Get<float>();
            AscendC::Cast(data, xInL_, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
            // Find max
            float maxVal = data(0);
            for (int32_t i = 1; i < tiling_.N; ++i) { float v = data(i); if (v > maxVal) maxVal = v; }
            // Subtract max via vector
            AscendC::Adds(data, data, -maxVal, tiling_.N);
            // Vector exp
            AscendC::Exp(data, data, tiling_.N);
            // Scalar sum
            float sumVal = 0.0f;
            for (int32_t i = 0; i < tiling_.N; ++i) sumVal += data(i);
            // Vector divide by sum
            float invSum = 1.0f / sumVal;
            AscendC::Muls(data, data, invSum, tiling_.N);
            // Cast back
            AscendC::Cast(yOutL_, data, AscendC::RoundMode::CAST_NONE, tiling_.N);
            AscendC::PipeBarrier<PIPE_V>();
        }
        yOutQ_.EnQue(yOutL_); xInQ_.FreeTensor(xInL_);
    }
    __aicore__ inline void ProcessRow(int ri) { CopyIn(ri); ComputeRow(ri); CopyOut(ri); }
private:
    SoftmaxV2KernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> xGM_, yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> xInQ_; AscendC::TQue<AscendC::TPosition::VECOUT,0> yOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> workBuf_;
    AscendC::LocalTensor<T> xInL_, yOutL_;
};
#endif

