#pragma once
#ifndef SWI_GLU_KERNEL_H
#define SWI_GLU_KERNEL_H
#include "kernel_operator.h"
#include "kernel_common.h"
#include "swi_glu_tiling.h"

constexpr int32_t SWI_GLU_CHUNK = 64;

template <typename T>
class SwiGluKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe) {
        CopyTiling(&tiling_, tilingGM);
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.M * tiling_.N);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.M * tiling_.N / 2);
        if ASCEND_IS_AIV {
            pipe_ = pipe; subBlockRows_ = tiling_.blockM / AscendC::GetSubBlockNum();
            pipe_->InitBuffer(xInQ_, 1, tiling_.N * sizeof(T));
            pipe_->InitBuffer(yOutQ_, 1, tiling_.N / 2 * sizeof(T));
            pipe_->InitBuffer(w1_, SWI_GLU_CHUNK * sizeof(float));
            pipe_->InitBuffer(w2_, SWI_GLU_CHUNK * sizeof(float));
            pipe_->InitBuffer(w3_, SWI_GLU_CHUNK * sizeof(float));
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int ci = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
            const int si = AscendC::GetSubBlockIdx();
            for (int li = 0; li < tiling_.tasksPerCore; ++li) {
                const int bx = ci * tiling_.tasksPerCore + li;
                if (bx >= BlockCount()) continue;
                for (int r = 0; r < subBlockRows_; ++r) {
                    const int ri = bx * tiling_.blockM + si * subBlockRows_ + r;
                    if (ri < tiling_.M) ProcessRow(ri);
                }
            }
        }
    }
private:
    __aicore__ inline int32_t BlockCount() const { return (tiling_.M + tiling_.blockM - 1) / tiling_.blockM; }
    __aicore__ inline void CopyIn(int32_t ri) {
        xInQ_.AllocTensor<T>(xInL_); AscendC::DataCopy(xInL_, xGM_[ri * tiling_.N], tiling_.N); xInQ_.EnQue(xInL_);
    }
    __aicore__ inline void CopyOut(int32_t ri) {
        yOutQ_.DeQue<T>(yOutL_); AscendC::DataCopy(yGM_[ri * tiling_.N / 2], yOutL_, tiling_.N / 2); yOutQ_.FreeTensor(yOutL_);
    }
    __aicore__ inline void ComputeRow(int32_t ri) {
        xInQ_.DeQue<T>(xInL_); yOutQ_.AllocTensor<T>(yOutL_);
        const int32_t half = tiling_.N / 2;

        // Process in chunks using ONLY AscendC vector ops (no scalar math)
        for (int32_t start = 0; start < half; start += SWI_GLU_CHUNK) {
            int32_t chunk = (start + SWI_GLU_CHUNK <= half) ? SWI_GLU_CHUNK : (half - start);
            auto x1Wk = w1_.Get<float>();
            auto x2Wk = w2_.Get<float>();
            auto x2Orig = w3_.Get<float>();

            // Load x1 and x2 (cast if not float, reinterpret if float)
            if constexpr (std::is_same_v<T, float>) {
                auto src = xInL_.template ReinterpretCast<float>();
                // Copy x1 and x2 to working buffers
                for (int32_t i = 0; i < chunk; ++i) {
                    x1Wk(i) = src(start + i);
                    x2Wk(i) = src(half + start + i);
                    x2Orig(i) = src(half + start + i);
                }
            } else {
                AscendC::Cast(x1Wk, xInL_[start], AscendC::RoundMode::CAST_NONE, chunk);
                AscendC::Cast(x2Wk, xInL_[half + start], AscendC::RoundMode::CAST_NONE, chunk);
                AscendC::Cast(x2Orig, xInL_[half + start], AscendC::RoundMode::CAST_NONE, chunk);
                AscendC::PipeBarrier<PIPE_V>();
            }

            // Sigmoid on x2Wk: 0.5 * (1 + tanh(x/2))
            AscendC::Muls(x2Wk, x2Wk, 0.5f, chunk);
            AscendC::Tanh(x2Wk, x2Wk, chunk);
            AscendC::Adds(x2Wk, x2Wk, 1.0f, chunk);
            AscendC::Muls(x2Wk, x2Wk, 0.5f, chunk);

            // SiLU: x2Wk = x2_orig * sigmoid
            AscendC::Mul(x2Wk, x2Orig, x2Wk, chunk);

            // Result: x1Wk = x1 * SiLU(x2)
            AscendC::Mul(x1Wk, x1Wk, x2Wk, chunk);

            // Store output
            if constexpr (std::is_same_v<T, float>) {
                auto dst = yOutL_.template ReinterpretCast<float>();
                for (int32_t i = 0; i < chunk; ++i) dst(start + i) = x1Wk(i);
            } else {
                AscendC::Cast(yOutL_[start], x1Wk, AscendC::RoundMode::CAST_NONE, chunk);
                AscendC::PipeBarrier<PIPE_V>();
            }
        }
        yOutQ_.EnQue(yOutL_); xInQ_.FreeTensor(xInL_);
    }
    __aicore__ inline void ProcessRow(int ri) { CopyIn(ri); ComputeRow(ri); CopyOut(ri); }
private:
    SwiGluKernelTiling tiling_{}; AscendC::TPipe *pipe_{}; int subBlockRows_{};
    AscendC::GlobalTensor<T> xGM_, yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN,0> xInQ_; AscendC::TQue<AscendC::TPosition::VECOUT,0> yOutQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> w1_, w2_, w3_;
    AscendC::LocalTensor<T> xInL_, yOutL_;
};
#endif

